const modelOutput = $input.first().json.output;

// 🟩 Pega o comando original digitado pelo usuário
const userCommand = $('Edit Fields9').first().json.body.comando || null;

// 🟩 Expressão regular para encontrar o JSON dentro da string
const jsonMatch = modelOutput.match(/(\{[\s\S]*\})/);

if (jsonMatch && jsonMatch[0]) {
  try {
    const parsedJson = JSON.parse(jsonMatch[0]);

    // Caso 1️⃣: comandos IoT
    if (parsedJson.IOT_command && Array.isArray(parsedJson.IOT_command)) {
      parsedJson.IOT_command = parsedJson.IOT_command.map(cmd => {
        return {
          device: cmd.device || null,
          action: cmd.action || null,
          parameter: cmd.hasOwnProperty("parameter") ? cmd.parameter : null,
          additional_condit: cmd.additional_condit ? String(cmd.additional_condit) : "0"
        };
      });

      // ✅ Retorna também o comando original
      return {
        json: {
          type: "IOT",
          user_command: userCommand,
          ...parsedJson
        }
      };
    }

    // Caso 2️⃣: interação geral
    if (parsedJson.type_message === "general") {
      return {
        json: {
          type: "general",
          user_command: userCommand,
          message: parsedJson.message || ""
        }
      };
    }

    // Caso inesperado
    throw new Error("Formato JSON não reconhecido: " + JSON.stringify(parsedJson));

  } catch (error) {
    throw new Error("JSON extraído do modelo é inválido: " + jsonMatch[0]);
  }
}

// ❌ Nenhum JSON encontrado
throw new Error("Nenhum JSON encontrado na saída do modelo: " + modelOutput);

// Obtemos o valor vindo do input do nó anterior.                  // Pegamos o campo 'credenciais'
const rawString = $input.first().json.credenciais;                 // Armazena a string bruta para processamento

// Primeiro, removemos todas as aspas externas que atrapalham.     // Deixa apenas o conteúdo útil
const cleaned = rawString.replace(/^"+|"+$/g, "");                 // Remove aspas extras no início/fim

// Agora, dividimos a string pelo caractere ';'.                    // Cada parte representa um "campo":"valor"
const parts = cleaned.split(";").filter(Boolean);                  // Filtra itens vazios após split

// Criamos um objeto final onde iremos armazenar os pares.          // Será o JSON estruturado
const result = {};                                                // Inicializa o objeto de saída

// Para cada trecho, extraímos chave e valor.                       // A string está no padrão: "campo":"valor"
for (const part of parts) {                                       // Percorre cada item separado
  const [key, value] = part.split(":");                           // Divide chave e valor
  const formattedKey = key.replace(/"/g, "").trim();              // Remove aspas extras da chave
  const formattedValue = value.replace(/"/g, "").trim();          // Remove aspas extras do valor
  result[formattedKey] = formattedValue;                          // Armazena no objeto final
}

// Retornamos o objeto JSON estruturado.                            // Este será o output do nó Code
return [{ json: result }];                                        // n8n sempre retorna array de objetos
